from kohakutpu.language.examples.dsl.vector.softmax import softmax


def facts():
    used = DEV.dram.used
    outs, run = CALL.call(DEV, softmax, {"x": XS})
    return {
        "outs": {n: [list(a.shape), str(a.dtype)] for n, a in outs.items()},
        "kind": run.kind,
        "freed": DEV.dram.used == used,
    }
